// 文件上传WAF
function checkUpload($file) {
    // 扩展名白名单
    $allowedExts = ['jpg', 'jpeg', 'png', 'gif', 'pdf'];
    $ext = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));
    if (!in_array($ext, $allowedExts)) return false;

    // 检查危险内容
    $content = file_get_contents($file['tmp_name']);
    $dangerous = ['<?php', '<%', '<script', 'eval', 'system', 'exec'];
    foreach ($dangerous as $d) {
        if (stripos($content, $d) !== false) return false;
    }

    return true;
}

if (!checkUpload($_FILES['file'])) die('Upload blocked');

