// SSTI WAF - 注意：只过滤 {{ 是不够的！
function wafssti($str) {
    // 完整过滤
    $dangerous = ['{{', '}}', '{%', '%}', '${', '}', '#{', '==', '!='];
    foreach ($dangerous as $d) {
        if (strpos($str, $d) !== false) return false;
    }

    // 过滤模板关键字
    if (preg_match('/__class__|__mro__|__subclasses__|__globals__|__builtins__|config|self|request|application/i', $str)) {
        return false;
    }

    return true;
}

