// LFI/RFI WAF
function waflfi($str) {
    // 检测路径穿越
    if (preg_match('/\.\.\/|\.\.\\|\.\.%2f|\.\.%5c/i', $str)) return false;

    // 检测协议包装器
    if (preg_match('/php:\/\/|file:\/\/|data:\/\/|expect:\/\/|zip:\/\/|phar:\/\//i', $str)) return false;

    // 检测空字节截断
    if (strpos($str, "\x00") !== false) return false;

    return true;
}

