// SSRF WAF
function wafssrf($url) {
    // 检查协议
    if (!preg_match('/^https?:\/\//i', $url)) return false;

    // 检查内网IP
    $parsedUrl = parse_url($url);
    $host = $parsedUrl['host'] ?? '';

    // 禁止的IP范围
    $blocked = ['localhost', '127.', '10.', '172.16.', '192.168.', '0.', '::1', '[::]'];
    foreach ($blocked as $b) {
        if (stripos($host, $b) === 0) return false;
    }

    // 禁止的协议包装器
    $dangerous = ['file://', 'gopher://', 'dict://', 'ftp://', 'ldap://'];
    foreach ($dangerous as $d) {
        if (stripos($url, $d) !== false) return false;
    }

    return true;
}

