// Node.js SSRF WAF
const PRIVATE_IPS = ['localhost', '127.', '10.', '172.16.', '192.168.', '0.', '::1'];

function checkSsrf(url) {
    try {
        const parsedUrl = new URL(url);

        // 检查协议
        if (!['http:', 'https:'].includes(parsedUrl.protocol)) return false;

        // 检查内网IP
        for (const ip of PRIVATE_IPS) {
            if (parsedUrl.hostname.startsWith(ip) || parsedUrl.hostname === ip) {
                return false;
            }
        }

        return true;
    } catch {
        return false;
    }
}

