// 方法3：使用pickle时验证来源
import pickle
import hmac
import hashlib

def safe_loads(data, key):
    # 数据格式: hmac签名 + 实际数据
    signature = data[:32]
    payload = data[32:]
    expected_sig = hmac.new(key, payload, hashlib.sha256).digest()
    if not hmac.compare_digest(signature, expected_sig):
        raise ValueError("Invalid signature")
    return pickle.loads(payload)

